      "answer": "34 31. The filter keeps the rows labeled 1, 2, 4 and 5, with 12, 7, 15 and 9 km. A .loc slice runs over labels and includes its end, so loc[1:4] takes the labels 1, 2 and 4, which gives 34. The missing label 3 is no problem, because the labels are sorted. An .iloc slice runs over positions and stops before its end, so iloc[1:4] takes positions 1, 2 and 3, the rows labeled 2, 4 and 5, which gives 31.",
