      "prompt": "A shop charges 4 dollars to ship a parcel of up to 1 kg, 7 dollars above 1 kg and up to 5 kg, and 12 dollars above 5 kg. Its parcels weigh 0.5, 1.0, 3.0, 5.0 and 8.0 kg, so the fees should be 4, 4, 7, 7 and 12. Which line gives every parcel its fee?",
      "answer": "df[\"fee\"] = np.where(w <= 1, 4, np.where(w <= 5, 7, 12)). The outer np.where gives 4 wherever w <= 1. Only the other parcels reach the inner np.where, and among them w <= 5 picks out exactly the ones above 1 kg and up to 5 kg. That gives 4, 4, 7, 7, 12, with both boundary parcels in the cheaper tier as the rule says.",
