      "prompt": "PyTorch is called a define-by-run framework. Which description fits?",
      "answer": "Each operation runs at once on real values and is recorded as it goes, so the graph is whatever the Python code executed, branches and loops included. The graph exists only for the pass that built it. backward() uses it once, and the next forward pass records a fresh one from whatever code runs that time.",
