      "prompt": "You create a tensor with requires_grad=True. What does that setting change?",
      "answer": "PyTorch starts recording the operations applied to the tensor, so a later backward() can work out a gradient for it. The recorded operations form the computation graph. backward() walks that graph from the result back to the tensor and leaves the gradient in its grad field.",
