      "prompt": "A training loop stores the loss tensor itself in one version and the plain number it holds in the other, and both train the same model to the same accuracy. What is different about the first one?",
      "answer": "Its memory use grows with every batch, because each stored tensor keeps the computation graph of its batch alive. A loss tensor still points back through the graph of the operations that produced it. Storing the tensor keeps that graph alive, batch after batch, so memory climbs for as long as the loop runs. A Python float carries no history at all.",
