      "prompt": "Ten features each have variance 1, and every pair of them has correlation 0.3. Their 10 by 10 covariance matrix C has 1 on the diagonal and 0.3 everywhere else. Without an eigensolver, what fraction of the total variance tr(C) does the largest eigenvalue of C account for?",
      "answer": "0.37. Write C = 0.7 I + 0.3 J, where J is the all-ones matrix. J is an outer product, so it has rank 1: its eigenvalues are 10 along (1, ..., 1) and 0 nine times. Then 0.3 J has 3 and nine 0s, and adding 0.7 I adds 0.7 to each: 3.7 once and 0.7 nine times. Check: 3.7 + 9(0.7) = 10 = tr(C). The fraction is 3.7 / 10 = 0.37.",
