      "prompt": "A linear layer maps each input of length 10 to an output of length 4, so W has shape 4 by 10. In NumPy a batch of 32 inputs is stored one example per row and the layer computes Z = X @ W.T + b. Backpropagation has already produced G, of shape (32, 4), whose row n is the gradient of the mean loss with respect to that example's output. Which line computes the gradient with respect to W?",
      "answer": "dW = G.T @ X. For one example the lesson's rule gives (∇z L) x^T, a 4 × 10 outer product. W is used by every example, so its gradient is the sum of these outer products over the batch, and the sum over n of row n of G times row n of X is exactly G.T @ X, of shape (4, 10). L is the mean, so example n's loss enters it with weight 1/32, and that 1/32 is already inside row n of G: nothing more is divided. The bias is also used by every example: db = G.sum(axis=0).",
