      "prompt": "You check the backward pass of a small ReLU network with central differences, h = 1e-5, in float64. Every weight passes with a relative error below 1e-9 except one. That weight feeds a unit that computes z = w x + b and then max(0, z). On the example used for the check, the unit's input is x = 2 and its pre-activation is z = 3e-7. The relative error for that weight is 0.33. What is the most likely explanation?",
      "answer": "The step in w moves z across the corner of ReLU at 0, so the difference mixes the slopes on both sides. Nudging w by ±h moves z by ±2h = ±2 × 10^−5, far more than the 3 × 10^−7 between z and the corner. At w + h the unit is on (z = 2.03 × 10^−5) and at w − h it is off, so the estimate is u × 2.03 × 10^−5 / (2 × 10^−5) ≈ 1.015u against the true 2u, a relative error of 0.985 / 3.015 ≈ 0.33. The backward pass is probably right. Check this weight on an example whose pre-activations sit farther from 0, or with h below 1.5 × 10^−7.",
