      "answer": "0.576. There are C(12, 5) = 792 equally likely batches. C(8, 5) = 56 of them have no mislabelled image, and 4 × C(8, 4) = 4 × 70 = 280 have exactly one. The complement of 'at least 2' is 'none or one', so the probability is 1 − (56 + 280)/792 = 456/792 = 19/33 ≈ 0.576.",
