      "prompt": "A prize is hidden in one of three boxes, each equally likely. You point at box 1. The host knows where the prize is and must then open a box that you did not point at and that is empty. When both of the other boxes are empty, he opens box 3 with probability 3/4 and box 2 with probability 1/4. He opens box 3, and it is empty. What is the probability that the prize is in box 2?",
      "answer": "4/7. Take the three places the prize could be as hypotheses, each with prior 1/3. The likelihood of 'he opens box 3' is 3/4 if the prize is in box 1 (both others are empty, and he picks box 3 with probability 3/4), 1 if it is in box 2 (box 3 is his only option), and 0 if it is in box 3. Bayes' theorem gives box 2 the posterior (1/3)(1) / ((1/3)(3/4) + (1/3)(1) + 0) = 1 / (7/4) = 4/7. Box 1 gets the other 3/7.",
