      "answer": "0.125. The cross-entropy is the average surprise under q: 1/2 · 1 + 1/4 · 3 + 1/8 · 2 + 1/8 · 3 = 1.875 bits. The entropy of p is 1/2 · 1 + 1/4 · 2 + 1/8 · 3 + 1/8 · 3 = 1.75 bits, so KL = 1.875 − 1.75 = 0.125. Term by term: b adds 1/4 · log₂ 2 = 0.25 and c adds 1/8 · log₂(1/2) = −0.125. The uniform model has KL 0.25, so this model is closer to the source than uniform, and still not equal to it.",
