      "prompt": "A decision tree is grown to full depth on 200 training passengers with two columns, age and fare. Fares are positive and run from 3 to 245 dollars, with 27 passengers above 100. You try four changes to the fare column, each applied to the training rows before the tree is grown again with the same settings. Which change can make the new tree group the training passengers differently, that is, put two passengers in the same leaf who were in different leaves before, or the other way round?",
      "answer": "Capping fare at 100 dollars. Capping is not strictly increasing: it maps all 27 fares above 100 to one value, 100. A split between, say, 120 and 180 is then impossible, because both passengers have the same fare. If the full-depth tree used such a split to separate two passengers with different labels, the new tree cannot use it. It must look to another column, and if those two passengers agree on every other column, the new tree has to put them in one leaf. The other three changes are strictly increasing, so the same partitions of the training rows are available.",
