      "prompt": "A mail filter is trained on 500 spam and 500 genuine messages with one yes-no feature, whether a message contains a link, and 300 of the spam and 100 of the genuine messages have one. A pipeline bug then copies the feature, so every message has two identical link columns, and both a no-smoothing naive Bayes and an unpenalised logistic regression with an intercept are refitted on the two columns. Say what probability of spam each model now gives a message with a link.",
      "answer": "Naive Bayes 0.9, logistic regression 0.75. Each copy has likelihood ratio P(link | spam) / P(link | genuine) = 0.6 / 0.2 = 3, and naive Bayes treats the copies as independent evidence, so it multiplies the prior odds of 1 by 3 × 3 = 9: probability 9 / 10 = 0.9. The copy carries no new information, and 300 of the 400 messages with a link are spam, 0.75. Logistic regression's predictions do not change: only the sum of the two link weights enters the predictions, and the fit sets it where the single weight was, giving 0.75 again. Naive Bayes still predicts spam, but it has become overconfident.",
