      "prompt": "A courier fits an unpenalized logistic regression for whether a parcel arrives late on the distance and the region, with the region one-hot encoded and north as the dropped baseline. The same data is then refit with west dropped instead, keeping indicators for north and south. What are the new intercept and the new weight on south?",
      "answer": "Intercept -1.5, south 0.7. The predictions cannot change, because the two encodings span the same columns and there is no penalty to tell them apart. So match the log-odds of each region at distance 0. North was -1.2, south -1.2 + 0.4 = -0.8 and west -1.2 - 0.3 = -1.5. The new intercept is the baseline's log-odds, -1.5, and each indicator's weight is its region minus the baseline: south -0.8 - (-1.5) = 0.7, north -1.2 - (-1.5) = 0.3. The distance weight stays at 0.05.",
