      "answer": "ŷ = A sin(x + phi) + C. The phase looks like a parameter inside the function, but the angle-addition formula moves it out: A sin(x + φ) = (A cos φ) sin x + (A sin φ) cos x. Fit α, β and C on the columns sin x, cos x and 1, which are independent for spread-out x, then A = √(α² + β²) and φ is the angle whose cosine and sine are α / A and β / A. Every pair (α, β) comes from some (A, φ), so this minimizes the stated loss.",
