      "prompt": "A regressor scores five test targets, and every prediction is exactly 3 above its target, so the predictions rank the targets perfectly. Its total squared error is 45 while the targets' squared deviations from their own mean total 40. Decide what R-squared the grader reports.",
      "answer": "-0.125. Every residual is −3, so the squared errors sum to 5 × 9 = 45. The targets' squared deviations from their mean 5 are 16, 4, 0, 4 and 16, which sum to 40. So R² = 1 − 45/40 = −0.125: predicting 5 for every row would have scored better. Subtracting 3 from every prediction gives R² = 1, so a perfect ranking with an offset is the model's whole problem, and R² is the metric that sees it.",
