      "prompt": "A spam filter turns each email into a logit and reports the spam probability p, and it is trained with squared error on that probability, so for a spam email the size of one gradient step's raise of the logit depends on p. At which value of p is that raise the largest, and how does squared error's step on a spam email it is surest is genuine compare with cross-entropy's step on the same email?",
      "answer": "At p = 1/3. The chain rule gives ∂L/∂z = 2(p − 1) · p(1 − p), of size g(p) = 2p(1 − p)². Its derivative is 2(1 − p)(1 − 3p), zero at p = 1/3, where g = 8/27 = 0.296. Below 1/3 the raise shrinks with p: at p = 0.05 it is 0.0903, while cross-entropy would raise the same logit by 0.95, about 10.5 times as much. Squared error spends its largest steps on spam that is only moderately misjudged.",
