      "answer": "Both are near 0.23, because every split that uses the shared signal gives its credit to one of the two columns, and each column is picked about equally often. A split that uses the shared signal is credited to whichever copy it chose, and the two copies are chosen equally often. One run gives x0 0.23 and the copy 0.24, and the exact values shift with the data and the seed. Together they hold a little more than x0 held alone, 0.47, because the signal is now offered at more splits: a set of 3 columns out of 10 contains at least one copy with probability 8/15, against 1/3 before. A strong feature with a copy, or with a near copy, can look half as important as it is.",
