      "prompt": "A 28 by 28 grayscale image is to be turned into 8 feature maps of the same size. A dense layer that does this has about 4.9 million parameters. A convolutional layer with eight 3 by 3 kernels does it with 80. Where does the saving come from?",
      "answer": "One kernel, 9 weights and a bias, serves every position of the image, so the count depends on the kernel size and the channel counts and not on the size of the image. One kernel per output channel, used at every position: 8 kernels of 9 weights plus 8 biases is 80. Double the image's width and height and the convolutional layer still has 80 parameters, while the dense layer's count grows about 16 times.",
