      "prompt": "A teammate's forward pass for a three-class classifier runs without errors, but its probabilities disagree with a reference implementation. The logits in the cache match the reference, so the bug is in the line that turns them into probabilities. Which one of four softmax bugs reproduces the returned matrix exactly?",
      "answer": "ReLU is applied to the logits before the softmax. Clipping the negative logits to 0 turns the first row into (1.2, 0, 0.4). Its exponentials are 3.320, 1 and 1.492, which sum to 5.812, giving 0.5713, 0.1721 and 0.2567. The second row becomes (0, 0.9, 2.1) and matches the same way. The correct first row is 0.6254, 0.0935 and 0.2810: the clipped logit of minus 0.7 gained probability and the others lost it.",
