      "prompt": "A classifier for 10 classes prints a loss of 147.4 on the first batch of 64 images before any training, with every logit within 0.01 of zero. Pick the bug that explains that number.",
      "answer": "The loss adds up the 64 losses of the images in the batch instead of averaging them. Near-zero logits give every class a probability of about 1/10, so each image's loss is minus ln 0.1 = ln 10 = 2.303, whatever its label. Adding up 64 of them gives 64 × 2.303 = 147.4, while the batch mean the training loop expects is 2.303. Comparing the first loss with ln C for C classes catches this before training starts.",
