      "url": "/theory/?id=bp-rank-of-output-gradient",
      "tags": [
        "Theory",
        "Multiple choice",
        "Round 2",
      ],
      "prompt": "A ten-class image classifier ends in a linear layer with a 10 by 256 weight matrix, followed by a softmax and the mean cross-entropy loss over a batch of 32 images. What is the largest rank the weight gradient can have on one batch, and what property of the per-image output errors caps it there?",
      "answer": "9. The batch gradient is the sum over the 32 images of the outer product of the output error with the hidden activations, so its columns are combinations of the 32 output errors. Each output error is predicted minus true probabilities, and both sum to 1 over the ten classes, so every error has entries summing to 0. All 32 errors lie in that 9-dimensional subspace of the 10 output directions, and so does every column of the gradient, which caps the rank at 9. Generic activations reach 9.",
