      "prompt": "A regression network has three tanh hidden units and three linear outputs and is trained on half the squared error. On one example the hidden activations are 0.8, -0.6 and 0.5, the prediction is 2.5, -1, 1.5 against the target 2, 0, 1, and the rows of the output weight matrix are given. Working backward through the tanh, what is the error at the pre-activation of the second hidden unit?",
      "answer": "0.96. The output units are linear and the loss is half the squared error, so the output error is ŷ − y = (0.5, −1, 0.5). Unit 2 feeds the outputs through column 2 of W2, (2, 0, 1), so the gradient at its activation is 1.0 + 0 + 0.5 = 1.5. The slope of tanh is 1 − tanh², which here is 1 − 0.36 = 0.64, so the error is 1.5 × 0.64 = 0.96.",
