      "prompt": "A bank's model scores 1,000 past loans, of which 800 were repaid and 200 defaulted, and the label codes a repaid loan as 1, so its reported precision 0.96 and recall 0.9 treat repaid as the positive class. The risk team treats a default as the positive case instead, where the model flags a loan by refusing it: what is the model's precision on defaults?",
      "answer": "0.68. Rebuild the counts from the repaid side. Recall 0.90 on the 800 repaid loans means the model would have approved 720 of them and refused 80. Precision 0.96 means those 720 are 96% of the loans it would have approved, so it would have approved 750, and 30 of those defaulted. It would have refused the other 250, and they hold the other 170 defaults, so the precision on defaults is 170 / 250 = 0.68. The 80 good borrowers it would turn away are about a third of its refusals, while the 30 defaults it would let through are only 4% of its approvals.",
