      "prompt": "A classifier has TP = 40, FP = 40 and FN = 20 on a validation set. Fix A turns ten false negatives into true positives and fix B turns ten false positives into true negatives. Which of the two raises F1 more?",
      "answer": "Fix A, because its ten corrected predictions become true positives, which F1 counts in its numerator as well as its denominator. Both fixes cut the error term (FP + FN) / 2 from 30 to 25. Fix A also adds 10 true positives, and TP sits in the numerator of F1 = TP / (TP + (FP + FN) / 2) as well as the denominator, while the true negatives fix B creates never enter F1. So fix A gives 50 / (50 + 25) = 0.667 against 40 / (40 + 25) = 0.615 for fix B, both up from 40 / 70 = 0.571. Fix B raises precision further (0.571 against 0.556), but fix A also lifts recall from 0.667 to 0.833.",
