      "prompt": "A logger records four readings, (-2, 2), (2, 2), (-2, 4) and (2, 4), and a script runs PCA on them without subtracting the column means, taking the top eigenvector of the raw Gram matrix over n minus 1. Which component does the script report as the first one, and what fraction of the variance does it print?",
      "answer": "First component (0, 1), explaining 5/7 ~ 0.714. From the raw rows, the cross terms cancel, (−4) + 4 + (−8) + 8 = 0, and the diagonal is (4 + 4 + 4 + 4) / 3 = 16/3 and (4 + 4 + 16 + 16) / 3 = 40/3. So M = diag(16/3, 40/3), its top eigenvector is (0, 1), and the printed share is 40 / 56 = 5/7. In general M is the covariance plus n / (n − 1) times the outer product of the mean with itself. Here the mean (0, 3) adds 12 to the second diagonal entry, more than the 16/3 of real spread along the first channel, so the script reports the direction in which the readings vary least.",
