      "prompt": "A plant records 400 vibration readings per pump sample. A worn bearing makes the same hum as a healthy one but its whole trace is about three times as large, and the hum can start anywhere in the sample. Which preprocessing step leaves a classifier with nothing to tell worn pumps from healthy ones?",
      "answer": "Subtracting each sample's own mean and dividing by its own standard deviation. Dividing each sample by its own standard deviation removes its overall size, and here the size is the only difference between the classes. After it, a worn pump's trace and a healthy pump's trace are the same signal at the same scale, so no model downstream can separate them. Per-series normalization helps when scale is a nuisance, such as a sensor's gain, and here it is the label.",
