      "answer": "About 340. The eigenvalues of [[1, ρ], [ρ, 1]] are 1 + ρ and 1 - ρ, along (1, 1) and (1, -1), so the Hessian's are 3.92 and 0.08 and the condition number is κ = 49. With η = 1/3.92 the flat direction shrinks by 1 - 1/49 per step, and 1,000-fold takes about 49 · ln 1000, roughly 7 · 49 = 343 (336 steps when counted). Standardizing fixes scale, not correlation: here the two temperatures move together, so the data say little about their difference, and that direction of the loss is nearly flat.",
