      "prompt": "Four candidate losses depend on one weight w. Three are convex on their whole domain. Which one is not, and what is the counterexample that proves it?",
      "answer": "Take the absolute value of w, subtract 1 and square it. Its value is 1 at w = 0 and 0 at both w = -1 and w = 1. The chord from (-1, 0) to (1, 0) has height 0 at w = 0, below the graph's 1, so the definition fails. The trap is the reasoning 'a square of a convex function is convex': the absolute value of w minus 1 is convex, but it goes negative, and squaring flips the part below zero into a bump. For w between -1 and 1 the function is the square of one minus the absolute value of w, which has its maximum at 0.",
