      "prompt": "After predicting \"on\", the model runs again on \"the cat sat on\". The new token \"on\" has the embedding (−1, −1, 0, 1) and sits at position 3, and head 1 of this model copies dimensions 3 and 4 of a token's vector into its query and dimensions 2 and 3 into its key. The head 1 keys of the first three tokens are (1.000, 0.000) for \"the\", (1.540, 1.010) for \"cat\" and (−0.416, 1.020) for \"sat\". In head 1, the query of \"on\" is compared with the keys of all four tokens, its own included. Which key gives the largest dot product?",
      "answer": "The key of \"cat\". Position 3 adds (sin 3, cos 3, sin 0.03, cos 0.03) = (0.14112, −0.98999, 0.03000, 0.99955), so the vector of \"on\" is (−0.85888, −1.98999, 0.03000, 1.99955). Head 1's query copies dimensions 3 and 4, (0.03000, 1.99955), and its key copies dimensions 2 and 3, (−1.98999, 0.03000). The dot products are 0.030 with \"the\", 0.03000 × 1.540 + 1.99955 × 1.010 = 2.066 with \"cat\", 0.03000 × (−0.416) + 1.99955 × 1.020 = 2.027 with \"sat\", and 0.0003 with itself. The key of \"cat\" wins by only about 0.04: the second number of the query is large, and the second numbers of the keys of \"cat\" and \"sat\" are almost equal.",
