      "prompt": "Head 2 of the running example makes its queries and keys with the same weights, so every token's query equals its own key. Picture a head built the same way, but with a head size of 48, in which every number of every query is +1 or −1, independently and with equal chance. A token's score against itself is its query times its own key, divided by $\\sqrt{48}$. What is that score?",
      "answer": "6.928. The query times itself adds 48 squares, each equal to 1, so it is exactly 48 every time, and the score is 48 divided by the square root of 48, which is the square root of 48 again, about 6.928. A score against another token adds 48 products of +1 or −1 that average 0, so after the division it averages 0 with a typical size of 1. The token's own score sits far above the others, so the softmax of Step 6 puts almost all the weight on the token itself. The gap grows with the square root of the head size, so a larger head makes it worse. Separate query and key weights avoid this.",
