      "prompt": "A training sentence has three of its pieces chosen by BERT's masking recipe: one is replaced by the mask, one by a random piece, and one is left as it is. Given the model's output probabilities at the three chosen positions, what is the masked-LM loss for the sentence?",
      "answer": "0.611. Every chosen position is asked for its original piece, whatever it shows. The three losses are −ln 0.4 = 0.916 for ferry, −ln 0.5 = 0.693 for left and −ln 0.8 = 0.223 for dawn, and their mean is 1.833 / 3 = 0.611. Position 3 is scored on left, not on the violin the model was shown, and position 7 counts although the model could see its answer.",
