      "prompt": "A reading-comprehension model is built on an encoder whose signature is encoder(input_ids, attention_mask, segment_ids). Both the training code and the test code call it as encoder(input_ids, segment_ids, attention_mask), so the two 0/1 arrays arrive in each other's places, and nothing raises an error. Each input is [CLS], a question, [SEP], a passage, [SEP], then [PAD]s. Its segment ids are 0 for [CLS], the question and the first [SEP], 1 for the passage and the last [SEP], and 0 for the padding. The model picks each answer from the outputs at the passage's positions. How does the swap change what those outputs can depend on?",
      "answer": "They no longer depend on the question at all: in every layer, no position can attend to [CLS], the question or the first [SEP]. Used as the attention mask, the segment ids are 1 only at the passage and the last [SEP]. Every other position is hidden as a key in every layer, so the vectors at the passage's positions are built from the passage and the last [SEP] alone. The question still enters the input, but nothing at its positions ever reaches a passage position. Trained this way, the model can only learn a question-blind guess, such as the span that most often holds an answer in a passage like this one. The real mask, used as segment ids, also gives every real piece the same segment embedding, but with the question out of reach that changes little.",
