      "prompt": "A toy language model with a vocabulary of four tokens is served through an interface that returns probabilities, not logits. For one prompt it returns 0.64, 0.16, 0.16 and 0.04. You want to sample the next token at temperature tau = 2. What probability should the least likely token get?",
      "answer": "0.111. The softmax does not change when the same constant is added to every logit, so the logs of the probabilities can serve as the logits. Dividing them by 2 and exponentiating gives the square roots 0.8, 0.4, 0.4 and 0.2, which add up to 1.8. The last token gets 0.2 / 1.8 = 1/9 = 0.111, almost three times its 0.04, and the first falls from 0.64 to 0.444.",
