      "prompt": "A retrieval model is trained with the InfoNCE loss at temperature 0.1. For one query the batch holds its matching key and two keys that do not match, so what is the loss for that query?",
      "answer": "0.230. The lengths are 3, 7, 9 and 3, so the cosine similarities with q are 20/21 = 0.952 for the positive, 22/27 = 0.815 for the first negative and 4/9 = 0.444 for the second. Divided by 0.1 they give the logits 9.52, 8.15 and 4.44, and the loss is ln(e^9.52 + e^8.15 + e^4.44) − 9.52 = ln(1 + e^−1.38 + e^−5.08) ≈ 0.230. The softmax puts 0.79 on the positive and 0.20 on the first negative, so almost all of the remaining loss comes from that one close negative.",
