      "prompt": "A fruit packing plant pretrains an image encoder with SimCLR on two million unlabeled conveyor-belt photos, building each view with a random crop covering 30 to 100% of it, a random horizontal flip, a hue shift of up to half the color wheel in either direction, and a conversion to grayscale with probability 0.5. A linear classifier trained on the frozen features then scores 94% at telling apples, pears and plums apart but only 61% at telling ripe bananas from unripe ones, which differ mainly in color. Which change to the pretraining is most likely to raise the ripeness score?",
      "answer": "Remove the hue shift and the grayscale conversion, and keep the crops and flips. The encoder learns what the two views of a photo have in common, so every augmentation names a feature it is taught to ignore. The hue shift and the grayscale conversion tell it to ignore color, the one thing that separates ripe from unripe bananas. Without them, color is the same in both views and becomes useful for matching. The price is a risk: with crops alone, two views of a photo can be matched by their color histograms instead of their content. A mild hue shift is a reasonable middle ground, but a shift of half the wheel erases exactly what this task needs.",
