      "answer": "It optimizes a different objective: each row's softmax covers 256 captions instead of 4,096, so an untrained model starts near ln 256 = 5.55 rather than ln 4096 = 8.32. The batch is where the negatives come from, so cutting it into micro-batches cuts the task. Each row picks its caption out of 256, the mutual-information bound tops out at ln 256, and the loss curve cannot be compared with a run on full batches. The full-batch loss fits in the same memory with more compute: embed all 4,096 pairs without keeping activations, compute the loss and its gradient with respect to the embeddings, then rerun each micro-batch with activations kept and backpropagate those gradients into the encoders.",
