      "answer": "0.918 bits. Y is 1 with probability 2/3, so H(Y) = −(2/3) log2(2/3) − (1/3) log2(1/3) = 0.918 bits. Knowing X fixes Y, so H(Y | X) = 0 and the mutual information is H(Y) − H(Y | X) = 0.918. The same comes from the other side: H(X) − H(X | Y) = 1.585 − 0.667. X is the most informative feature Y could have, uncorrelated or not.",
