      "prompt": "You fine-tune a 24-layer encoder for classification in PyTorch and can afford to train only half of its layers. Plan A freezes layers 1 to 12, the ones nearest the input, and trains layers 13 to 24. Plan B freezes layers 13 to 24 and trains layers 1 to 12. The embeddings stay frozen in both plans, and every step runs the whole forward pass. Count the cost of one training step in units, where one unit is one layer's forward pass. In the backward pass, computing a layer's gradient with respect to its input costs one unit, and computing the gradients of its weights costs another unit. Ignore the classification head. What does a step cost under each plan?",
      "answer": "Plan A costs 47 units and plan B costs 59. Both run 24 units forward. Plan A computes 12 weight gradients and the input gradients of layers 24 down to 14, which carry the gradient to the trainable layers below them, 11 units: 47 in all. Layer 13 needs no input gradient, since only frozen layers sit under it. Plan B must carry the gradient back through the 12 frozen layers on top, 12 units, then computes 12 weight gradients and 11 input gradients for layers 12 down to 2: 59 in all. Training every layer would cost 24 + 24 + 23 = 71. Plan A also need not store the activations inside layers 1 to 12, since no gradient flows back into them.",
