      "prompt": "A LoRA layer computes W_0 x + alpha/r BAx with W_0 frozen. A teammate initializes B with small random entries and A with zeros, the other way round from the usual recipe, and trains with plain gradient descent. Which describes the first two steps?",
      "answer": "The layer starts at W₀, only A changes on the first step, and B starts changing on the second. With A = 0 the product BA is zero, so training starts from the pretrained layer. For an output gradient g, the gradient of B is (α/r) g (Ax)ᵀ, which is zero while A is zero, and the gradient of A is (α/r) Bᵀ g xᵀ, which is not zero because B is random. After the first step A is no longer zero, so B's gradient is not zero either. The swapped start trains too, and the only difference is which factor moves first.",
