      "prompt": "A recurrent model's gradients on one batch have length 12 for W_hh, length 4 for W_xh, and the bias gradient is (1.8, -2.4). Between loss.backward() and optimizer.step() the loop calls PyTorch's clip_grad_norm_ with a threshold of 2.0. What gradient does the optimizer then use for the bias?",
      "answer": "(0.28, -0.37). The three tensors form one gradient of length √(12² + 4² + 3²) = √169 = 13. That is above 2, so every entry of every tensor is multiplied by 2/13 ≈ 0.154. The bias gradient becomes (1.8, −2.4) × 2/13 ≈ (0.28, −0.37), and the other two shrink by the same factor, to lengths 1.85 and 0.62. The update points the same way as before and has length 2.",
