      "prompt": "A teammate's GRU writes the update gate's blend the other way round: their gate keeps the old state where yours keeps the candidate, with the reset gate and the candidate computed the same way. Which update-gate weights and bias make the two GRUs compute exactly the same function?",
      "answer": "W'_z = -W_z and b'_z = -b_z. The teammate's gate has to equal 1 − z at every step. For any pre-activation a, 1 − σ(a) = e^(−a) / (1 + e^(−a)) = 1 / (1 + e^a) = σ(−a). Negating every weight and the bias turns the teammate's pre-activation into −a, so its gate is σ(−a) = 1 − z and the two updates agree term by term. Nothing else changes.",
