      "prompt": "A rail company's help desk embeds questions and notes as dense vectors and retrieves notes by cosine similarity. To save time it keeps a cache. When a new question has cosine similarity at least 0.96 with a question it has already answered, it skips retrieval and reuses the notes found for that earlier question. One earlier question had cosine similarity 0.8 with its top note. A new question arrives with cosine similarity exactly 0.96 with it, and the help desk reuses that note. The embeddings have 768 entries. What is the lowest cosine similarity the new question can have with the note?",
      "answer": "0.6. Split each vector into its part along the earlier question and the rest. As unit vectors, the new question is 0.96 times the earlier question plus 0.28 times a unit vector u perpendicular to it (0.96² + 0.28² = 1), and the note is 0.8 times the earlier question plus 0.6 times a unit vector w perpendicular to it. Their dot product is 0.96 × 0.8 + 0.28 × 0.6 × (u · w), and u · w is at least −1, so the cosine is at least 0.768 − 0.168 = 0.6. It equals 0.6 when u and w point opposite ways: all three vectors lie in one plane with the earlier question between the other two, and the angles of about 16.3° and 36.9° add up to about 53.1°.",
