      "prompt": "Porting RoPE to a new codebase, an engineer flips the sign of the sine terms in the key rotation only. Queries are still rotated by R_m, but the key at position n is now rotated by R_n^T, a turn of -ntheta. In two dimensions, what does the score < R_mq, R_n^T k> depend on?",
      "answer": "The sum m + n, so two tokens a fixed distance apart score differently in different places. (R_m q)ᵀ(R_nᵀ k) = qᵀ R_mᵀ R_nᵀ k, and both factors are turns by negative angles, −mθ and −nθ, so they add to a turn by −(m + n)θ. Positions 5 and 2 now score like positions 4 and 3, while positions 8 and 5, three apart like the first pair, score differently. A check that the score matrix is constant along its diagonals, as in From scratch, catches the bug at once.",
