      "prompt": "RoPE code comes in two layouts. Both turn pair i by the angle mtheta_i, with theta_i = 10000^-2i/d. The interleaved layout, used in this lesson, makes pair i from coordinates 2i and 2i + 1. The half-split layout makes pair i from coordinates i and i + d/2. A checkpoint was trained with half-split RoPE. You load its W_Q and W_K, unchanged, into a model whose attention uses the interleaved layout. What happens to the attention scores?",
      "answer": "The scores stay relative but differ from training, and moving rows i and i + d/2 of W_Q and W_K to rows 2i and 2i + 1 restores the trained scores. Any split into pairs keeps the score relative, so the loaded model still computes a function of n − m, but each feature now turns with a different partner and at a different speed than in training. Let P send coordinate i to 2i and coordinate i + d/2 to 2i + 1. Interleaved RoPE of P x is P times half-split RoPE of x, so with P W_Q and P W_K the queries and keys are the trained ones, both reordered by P, and a shared reordering leaves every dot product unchanged.",
