      "prompt": "A model with RoPE (base 10,000) was trained on sequences of 8,192 tokens. You run it over a 100,000-token server log and keep only the 8,000 most recent tokens in its cache, so each query attends to itself and the 7,999 tokens before it. Positions are counted from the start of the log, so they reach 99,999. What should you change about the positions?",
      "answer": "Nothing, because every score depends only on an offset between 0 and 7,999, and training produced every one of those offsets. By the cancellation, each pair's term depends on its speed times the offset between query and key, never on the positions themselves. With this cache the largest offset is 7,999, below the 8,191 of training, so every angle a score uses was met in training, on every pair. Large positions cost only rounding: in float32 an angle near 100,000 radians is stored to within about 0.004 radians. A window that has evicted the first tokens of the log can still fail, but not because of positions: many heads put much of their weight on the first few tokens, and those are gone.",
