      "answer": "From the second layer on, they change with the question, since each visual position attends to the question. Under the causal mask a position sees itself and everything before it, and the question now comes before the photo. The first layer reads the visual tokens themselves, but each later layer reads hidden states that have already mixed in the question, so stored keys and values are right only for the question they were computed with. With the photo first, its positions see nothing but the photo, and their keys and values can be stored once per photo.",
