      "answer": "(0.06, -0.3, 0.09, 0.15). The logits reach the loss only through the weight w = g2, and dL/dw = (dL/dy) · E2(x) = 0.4 − 1.2 − 0.4 = −1.2. The softmax derivative is dg2/dz2 = g2(1 − g2) = 0.25 and dg2/dzj = −g2 gj for the other three. So dL/dz2 = −1.2 × 0.25 = −0.3, and each other logit gets −1.2 × (−0.5 gj) = 0.6 gj: 0.06, 0.09 and 0.15. A descent step raises z2 and lowers the other three, so expert 2's weight grows, because a larger copy of its output lowers the loss. The four entries add to zero: adding the same number to every logit leaves the softmax unchanged.",
