      "prompt": "In a state an agent can wait, which pays 1 and leaves it in the same state, or go, which pays 5.6 and ends the episode. Its policy picks each action half the time, the discount is 0.9, and evaluating it gives 6.4 for waiting and 5.6 for going. How much does the value of the state rise when the agent switches to waiting at every visit?",
      "answer": "4.0. Before the switch, V^π(s) averages the two actions with the policy's probabilities: 0.5(6.4) + 0.5(5.6) = 6. Always waiting earns 1 at every step forever, worth 1 + 0.9 + 0.81 + ... = 1/(1 − 0.9) = 10. The rise is 10 − 6 = 4, ten times the 0.4 that the Q table seems to promise, because Q^π(s, wait) assumes the old policy takes over again from the next step.",
