      "prompt": "A Q-learning agent in one state picks among 4 actions with an epsilon-greedy policy whose exploration rate follows a schedule, and one action there is never the greedy choice. Which schedule still tries that action infinitely often with probability 1?",
      "answer": "epsilon_t = 1/t. At step t the agent tries b with probability 1/(4t). The chance of never trying it after step T is the product of (1 − 1/(4t)) over t > T, which is at most exp(−(1/4)(1/(T+1) + 1/(T+2) + ...)). The harmonic sum has no limit, so the product is 0 for every T: after any step, b is certain to be tried again. ε still goes to 0, just slowly enough.",
