      "prompt": "A delivery app sends each order along one of three routes with feature vectors (1, 0), (0, 2) and (2, 1), and a softmax policy over route scores picks them with probabilities 0.5, 0.3 and 0.2. One order takes route B and earns a return of 5. What is 5 times the gradient of the log probability of route B?",
      "answer": "(-4.5, 6). log π(B) is θ·φ(B) minus the log of the sum of exp(θ·φ(b)) over the routes. The first term has gradient φ(B) = (0, 2). The second has gradient equal to the sum of exp(θ·φ(b)) φ(b) divided by the sum of exp(θ·φ(b)), which is the average feature vector under the policy, 0.5(1, 0) + 0.3(0, 2) + 0.2(2, 1) = (0.9, 0.8). So the gradient of log π(B) is (−0.9, 1.2), and G = 5 gives (−4.5, 6). The first component is negative even though B earned a reward: B has less of the first feature than the policy's average route, so making B more likely means turning θ away from that feature.",
