      "prompt": "A warehouse robot at a junction takes a shortcut whose return is 5 or a long way whose return is 1, and a slipped baseline subtracts the average return of the state the robot moves to instead of the state it acts from. Which route does the policy at the junction come to prefer as training goes on?",
      "answer": "The long way, more and more strongly as training goes on. With accurate averages, b(X) = 6 and b(Y) = 0, so the slipped weights are (−1 + 6) − 6 = −1 for the shortcut and (1 + 0) − 0 = +1 for the long way: each step keeps only its own reward, and the 6 that the shortcut leads to is subtracted away. The expected change in the shortcut's logit at 50/50 is 0.5(0.5)(−1) + 0.5(−0.5)(+1) = −0.25. The two weights stay −1 and +1 whatever the policy at J does, so the shortcut keeps losing probability. The correct baseline, b(J) = 3, gives weights +2 and −2 and an expected change of +1.0 toward the shortcut, whose return of 5 beats the long way's 1. The slip turns the robot into one that chases the reward of the current step.",
