      "answer": "Samples 1, 3 and 5. Sample 1 is inside the band, so both terms are 2.2 and the gradient flows. Sample 2: 1.35 against 1.2, the minimum is the clipped 1.2, a constant, so no gradient. Sample 3: 2.1 against 2.4, the minimum is the unclipped 2.1, so the gradient flows and pushes the ratio back up. Sample 4: −0.6 against −0.8, the minimum is the clipped −0.8, no gradient. Sample 5: −3.0 against −2.4, the minimum is the unclipped −3.0, so the gradient flows and pushes the ratio back down. A sample stops only once its ratio has gone past the band on the side its advantage favors, which is the case for samples 2 and 4.",
