      "prompt": "After its message-passing layers, every node's state is a whole number from 0 to 3, and every graph has one to four nodes. The readout applies a fixed function f to each node's state and adds up the results. Which f gives different readouts to any two graphs whose node states differ as collections, ignoring order?",
      "answer": "f(x) = 5^x. Write the readout as c0 + 5 c1 + 25 c2 + 125 c3, where cx counts the nodes in state x. Each count is between 0 and 4, so these are the digits of the readout in base 5, and two different lists of counts give two different numbers. The base has to exceed the largest possible count, which is why base 4 fails. A sum can tell apart every collection, but only after a well-chosen f, which in practice is a learned network applied to each node before the sum.",
