      "prompt": "Every node of a graph carries one number and has at least one neighbor, and the target at each node is the plain average of the node's own number and its neighbors'. Four layers are offered, each with one output per node, the identity in place of the activation, and any weights you like. Which one outputs exactly that target at every node of every graph?",
      "answer": "A single GAT head, with its weight and attention vector chosen by hand. Set the weight to 1 and the attention vector to 0. Every score is then LeakyReLU(0) = 0, whatever the features, so the softmax gives each of the d_v + 1 nodes in the neighborhood, the node included, the same weight 1/(d_v + 1), and the output is t_v. The softmax divides by the size of each neighborhood on its own, which is the degree-dependent share that GCN and GraphSAGE cannot produce. If the half of the attention vector that multiplies the neighbor's z were not 0, the scores, and with them the weights, would change with the neighbors' features, and the average would no longer be plain.",
