      "prompt": "Every graph in a dataset has 12 nodes and an adjacency matrix but the nodes carry no features, so a model must build its input matrix from the adjacency alone. Which of four candidates keeps the stack of graph convolution layers permutation equivariant, so renumbering a graph only reorders the output rows?",
      "answer": "H = A(A1), one column holding for each node the sum of its neighbors' degrees. A1 is the vector of degrees, and multiplying it by A adds up each node's neighbors' degrees. After renumbering, the adjacency is P A P^T, and since P^T P = I and P^T 1 = 1 (a permutation leaves the all-ones vector alone), the new input is P A P^T P A P^T 1 = P A A 1. That is the old input with its rows moved like the nodes, the only property of H that the lesson's derivation uses, so every layer stays equivariant.",
